// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner = address(0x1);
    function setUp() public {
        c = new SimpleWallet();
    }
    function testFuzz_property(address caller, uint256 amount, bytes calldata data) public {
        vm.assume(caller != address(c));
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok;
        try c.sendMoney(address(0xdead), amount, data) { ok = true; } catch { ok = false; }
        assertTrue(caller == c.owner() ? ok : !ok);
    }
}
